# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>

__global__ void matmul_kernel(const half* A, const half* B, half* C, int M, int K) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M) {
        half sum = __hzero();
        for (int k = 0; k < K; ++k) {
            sum = __hadd(sum, __hmul(A[row * K + k], B[k]));
        }
        C[row] = sum;
    }
}

torch::Tensor matmul_forward(const torch::Tensor& A, const torch::Tensor& B) {
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions incompatible for multiplication");
    TORCH_CHECK(A.dtype() == torch::kFloat16, "A must be float16");
    TORCH_CHECK(B.dtype() == torch::kFloat16, "B must be float16");

    int M = A.size(0);
    int K = A.size(1);

    auto options = torch::TensorOptions().dtype(torch::kFloat16).device(torch::kCUDA);
    auto C = torch::empty({M, 1}, options);

    const half* A_ptr = A.data_ptr<half>();
    const half* B_ptr = B.data_ptr<half>();
    half* C_ptr = C.data_ptr<half>();

    const int block_size = 256;
    const int grid_size = (M + block_size - 1) / block_size;

    matmul_kernel<<<grid_size, block_size>>>(
        A_ptr, B_ptr, C_ptr, M, K
    );

    return C;
}
"""

